<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfileMiddleNameAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileMiddleNameAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfileMiddleNameAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getMiddleName returns null on a freshly created holder.
     */
    public function testMiddleNameNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileMiddleNameAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isMiddleNameAssigned());
        $this->assertNull($holder->getMiddleName());
    }
}
class ImplWithUserProfileMiddleNameAttributeHolderUnitTest
{
    use UserProfileMiddleNameAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedMiddleNameRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultMiddleName();
    }
}
